PAIRS.extend([
 ('Editor de imagens com ribbon moderna e integração com o desktop Linux.','Image editor with a modern ribbon and Linux desktop integration.'),
 ('Desenvolvimento:','Development:'),('Baseado em:','Based on:'),('Código Python sob licença MIT.','Python code under the MIT license.')])
PAIRS=[(pt.replace('\\n','\n'),en.replace('\\n','\n')) for pt,en in PAIRS]
_MAPS={lang:{source:(pt if lang=='pt' else en) for pt,en in PAIRS for source in (pt,en)} for lang in ('en','pt')}
_PREFIXES={lang:sorted([((en,pt) if lang=='pt' else (pt,en)) for pt,en in PAIRS if (en if lang=='pt' else pt).endswith((' ',': ','('))],key=lambda pair:len(pair[0]),reverse=True) for lang in ('en','pt')}

def language():
    return 'pt' if QLocale().language()==QLocale.Language.Portuguese else 'en'

def tr(value):
    if not isinstance(value,str):return value
    lang=language()
    if value in _MAPS[lang]:return _MAPS[lang][value]
    if ';;' in value:return ';;'.join(tr(part) for part in value.split(';;'))
    for source in ('Images','All files'):
        if value.startswith(source+' ('):return _MAPS[lang].get(source,source)+value[len(source):]
    for source,target in _PREFIXES[lang]:
        if value.startswith(source):return target+value[len(source):]
    if '\n' in value:return '\n'.join(tr(line) for line in value.split('\n'))
    return value
